from __future__ import annotations

import json
import re
from typing import Any, Dict, List, Optional

from config.settings import COMFYUI_PORT, SESSION_MEDIA_DIR

from .charts import ImageAttachment, bar_chart, line_chart


_CHART_WORDS = ("chart", "graph", "plot", "bar chart", "bar graph", "line chart")
_COMFY_WORDS = (
    "generate me a picture",
    "make a pic",
    "do a pic",
    "a pic would be nice",
    "generate an image",
    "create an image",
    "generate a photo",
    "create a photo",
)


def infer_image_intent(prompt: str) -> Optional[str]:
    pl = (prompt or "").lower()
    if any(w in pl for w in _CHART_WORDS):
        return "chart"
    if any(w in pl for w in _COMFY_WORDS) or re.search(r"\b(generate|create|make|draw)\s+(me\s+)?(an?\s+)?(image|picture|pic|photo|artwork|illustration)\b", pl):
        return "comfyui"
    return None


def _coerce_chart_spec_from_prompt(prompt: str) -> Dict[str, Any]:
    # Best-effort fallback when caller didn't pass a strict JSON spec.
    nums = [float(x) for x in re.findall(r"-?\d+(?:\.\d+)?", prompt)]
    is_line = "line" in prompt.lower()
    if is_line:
        x = list(range(1, len(nums) + 1)) or [1, 2, 3]
        y = nums or [1, 2, 3]
        return {"kind": "line", "title": "Line Chart", "x": x, "y": y, "x_label": "Index", "y_label": "Value"}
    labels = [f"Item {i+1}" for i in range(max(1, len(nums) or 3))]
    values = nums or [1, 2, 3]
    return {"kind": "bar", "title": "Bar Chart", "labels": labels[:len(values)], "values": values, "y_label": "Value"}


def generate_image(spec: Dict[str, Any]) -> List[Dict[str, Any]]:
    """
    spec example:
    {
      "kind": "bar",
      "title": "...",
      "labels": [...],
      "values": [...],
      "y_label": "Count"
    }
    """
    kind = (spec.get("kind") or "").strip().lower()
    if kind == "bar":
        att: ImageAttachment = bar_chart(
            title=spec.get("title", ""),
            labels=spec.get("labels", []),
            values=spec.get("values", []),
            y_label=spec.get("y_label"),
            out_dir=str(spec.get("out_dir") or SESSION_MEDIA_DIR),
        )
        return [att.__dict__]

    if kind == "line":
        att = line_chart(
            title=spec.get("title", ""),
            x=spec.get("x", []),
            y=spec.get("y", []),
            x_label=spec.get("x_label"),
            y_label=spec.get("y_label"),
            out_dir=str(spec.get("out_dir") or SESSION_MEDIA_DIR),
        )
        return [att.__dict__]

    if kind in {"comfy", "comfyui", "image"}:
        prompt = (spec.get("prompt") or "").strip()
        if not prompt:
            raise ValueError("ComfyUI image generation requires spec.prompt")
        base_url = str(spec.get("base_url") or f"http://127.0.0.1:{int(COMFYUI_PORT)}").strip()
        if base_url and "://" not in base_url:
            base_url = f"http://{base_url}"
        try:
            timeout_s = max(10, int(spec.get("timeout_s", 120)))
        except Exception:
            timeout_s = 120
        from .comfyui import generate_comfyui_image
        att = generate_comfyui_image(
            prompt=prompt,
            base_url=base_url,
            timeout_s=timeout_s,
            out_dir=str(spec.get("out_dir") or SESSION_MEDIA_DIR),
        )
        return [att.__dict__]

    raise ValueError(f"Unsupported image kind: {kind}")


def spec_from_text(prompt: str, provided_spec: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    if provided_spec is not None:
        if not isinstance(provided_spec, dict):
            raise ValueError("provided_spec must be a dict")
        direct = dict(provided_spec)
        nested = direct.get("spec")
        if isinstance(nested, dict):
            return dict(nested)
        return direct

    stripped = (prompt or "").strip()
    fenced = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", stripped, flags=re.DOTALL | re.IGNORECASE)
    if fenced:
        stripped = fenced.group(1).strip()
    if stripped.startswith("{") and stripped.endswith("}"):
        try:
            maybe = json.loads(stripped)
            if isinstance(maybe, dict):
                return maybe.get("spec", maybe)
        except json.JSONDecodeError:
            pass

    intent = infer_image_intent(prompt or "")
    if intent == "chart":
        return _coerce_chart_spec_from_prompt(prompt or "")
    if intent == "comfyui":
        return {"kind": "comfyui", "prompt": prompt}
    raise ValueError("Could not infer image generation spec")

﻿from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Dict, List


SCHEMA_DIR = Path("config/extraction_schemas")
DEFAULT_SCHEMA_PATH = SCHEMA_DIR / "default.json"


def ensure_default_schema_migrated() -> str:
    SCHEMA_DIR.mkdir(parents=True, exist_ok=True)
    if DEFAULT_SCHEMA_PATH.exists():
        return str(DEFAULT_SCHEMA_PATH)

    fields: List[str] = ["patient_name", "dob"]
    example: Dict[str, Any] = {"patient_name": "John Doe", "dob": "1990-01-01"}
    output_columns: List[str] = ["patient_name", "dob"]
    try:
        from config import extraction_schema as py_schema

        fields = list(getattr(py_schema, "EXTRACTION_FIELDS", fields)) or fields
        example = dict(getattr(py_schema, "EXAMPLE_ENTRY", example)) or example
        output_columns = list(getattr(py_schema, "OUTPUT_COLUMNS", fields)) or fields
    except Exception:
        pass

    payload = {
        "schema_id": "default",
        "version": "1.0",
        "fields": [{"name": f, "type": "text", "required": False} for f in fields],
        "output_columns": output_columns,
        "example": example,
    }
    DEFAULT_SCHEMA_PATH.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
    return str(DEFAULT_SCHEMA_PATH)


def load_schema(schema_id: str = "default") -> Dict[str, Any]:
    ensure_default_schema_migrated()
    path = SCHEMA_DIR / f"{schema_id}.json"
    if not path.exists():
        raise FileNotFoundError(f"Schema not found: {path}")
    data = json.loads(path.read_text(encoding="utf-8"))
    data.setdefault("fields", [])
    data.setdefault("output_columns", [f.get("name") for f in data["fields"] if f.get("name")])
    data.setdefault("example", {})
    data.setdefault("version", "1.0")
    return data


def schema_field_names(schema: Dict[str, Any]) -> List[str]:
    return [f.get("name") for f in schema.get("fields", []) if f.get("name")]


def schema_required_fields(schema: Dict[str, Any]) -> List[str]:
    return [f.get("name") for f in schema.get("fields", []) if f.get("required") and f.get("name")]


def schema_field_specs(schema: Dict[str, Any]) -> List[Dict[str, Any]]:
    return [dict(item) for item in list(schema.get("fields") or []) if isinstance(item, dict) and item.get("name")]


def schema_alias_map(schema: Dict[str, Any]) -> Dict[str, str]:
    alias_map: Dict[str, str] = {}
    for field in schema_field_specs(schema):
        name = str(field.get("name") or "").strip()
        if not name:
            continue
        aliases = [name, *[str(item) for item in list(field.get("aliases") or []) if str(item).strip()]]
        for alias in aliases:
            normalized = "".join(ch.lower() for ch in alias if ch.isalnum())
            if normalized:
                alias_map.setdefault(normalized, name)
    return alias_map

from __future__ import annotations

import shutil
from typing import Any

try:
    import psutil
except Exception:  # pragma: no cover
    psutil = None

from .profiles import RuntimeProfile, get_profile


def _memory_gb() -> float | None:
    if psutil is None:
        return None
    try:
        return round(float(psutil.virtual_memory().total) / float(1024**3), 2)
    except Exception:
        return None


def evaluate_rollout(profile: RuntimeProfile | dict[str, Any] | str) -> dict[str, Any]:
    resolved: RuntimeProfile | None
    if isinstance(profile, RuntimeProfile):
        resolved = profile
    elif isinstance(profile, dict):
        item = dict(profile)
        resolved = RuntimeProfile(
            profile_id=str(item.get("profile_id") or item.get("id") or "profile"),
            display_name=str(item.get("display_name") or item.get("profile_id") or "Profile"),
            description=str(item.get("description") or ""),
            allowed_backends=tuple(item.get("allowed_backends") or []),
            default_model_profile=str(item.get("default_model_profile") or "balanced"),
            max_risk_tier=str(item.get("max_risk_tier") or "LOW"),
            delivery_channels=tuple(item.get("delivery_channels") or []),
            rollout_gates=dict(item.get("rollout_gates") or {}),
            metadata=dict(item.get("metadata") or {}),
        )
    else:
        resolved = get_profile(str(profile or ""))

    if resolved is None:
        return {"ok": False, "issues": ["unknown_profile"], "checks": []}

    gates = dict(resolved.rollout_gates or {})
    checks: list[dict[str, Any]] = []
    issues: list[str] = []

    for executable in list(gates.get("required_executables") or []):
        ok = shutil.which(str(executable)) is not None
        checks.append({"name": f"executable:{executable}", "ok": ok})
        if not ok:
            issues.append(f"missing_executable:{executable}")

    for executable in list(gates.get("optional_executables") or []):
        ok = shutil.which(str(executable)) is not None
        checks.append({"name": f"optional_executable:{executable}", "ok": ok})

    min_memory_gb = gates.get("min_memory_gb")
    if min_memory_gb is not None:
        available = _memory_gb()
        ok = available is None or float(available) >= float(min_memory_gb)
        checks.append({"name": "memory_gb", "ok": ok, "required": float(min_memory_gb), "available": available})
        if not ok:
            issues.append(f"insufficient_memory:{available}")

    return {
        "ok": not issues,
        "issues": issues,
        "checks": checks,
        "profile": resolved.to_dict(),
    }

from __future__ import annotations

from datetime import datetime


class HeartbeatPolicy:
    def __init__(self, breadcrumb_minutes: int, dedupe_cooldown_seconds: int):
        self.breadcrumb_minutes = breadcrumb_minutes
        self.dedupe_cooldown_seconds = dedupe_cooldown_seconds
        self.last_breadcrumb_ts: datetime | None = None
        self._sig_last_ts: dict[str, datetime] = {}
        self._last_status_level = "INFO"
        self._last_paused = False

    def should_emit_ui_event(self, event: dict, now: datetime) -> bool:
        etype = event.get("type")
        level = event.get("level", "INFO")

        if etype == "tick":
            return False

        if etype == "lifecycle":
            return True

        if level in {"WARN", "ERROR"}:
            return True

        if etype == "status":
            paused = bool(event.get("meta", {}).get("paused", False))
            transitioned = (level != self._last_status_level) or (paused != self._last_paused)
            self._last_status_level = level
            self._last_paused = paused
            return transitioned

        return False

    def should_update_label(self, event: dict) -> bool:
        return event.get("type") in {"status", "lifecycle", "alert", "error"}

    def allow_breadcrumb(self, now: datetime) -> bool:
        if self.last_breadcrumb_ts is None:
            self.last_breadcrumb_ts = now
            return True
        elapsed_minutes = (now - self.last_breadcrumb_ts).total_seconds() / 60.0
        if elapsed_minutes >= self.breadcrumb_minutes:
            self.last_breadcrumb_ts = now
            return True
        return False

    def dedupe_ok(self, event_sig: str, now: datetime) -> bool:
        last = self._sig_last_ts.get(event_sig)
        if last is None:
            self._sig_last_ts[event_sig] = now
            return True
        elapsed = (now - last).total_seconds()
        if elapsed >= self.dedupe_cooldown_seconds:
            self._sig_last_ts[event_sig] = now
            return True
        return False

