from __future__ import annotations

import re
from typing import Any, Iterable

from config.settings import STRATEGIC_EXECUTION_BYPASS_PHRASES

FORBIDDEN_KEYS = {"proposal_action", "tool_call", "capability_request"}
MAX_ALLOWED_ARTIFACT_IDS = 15
MAX_CONTEXT_ARTIFACT_IDS = 15


def deep_scan_forbidden_keys(data: Any, path: str = "$") -> list[str]:
    errs: list[str] = []
    if isinstance(data, dict):
        for key, value in data.items():
            k = str(key)
            p = f"{path}.{k}"
            if k in FORBIDDEN_KEYS:
                errs.append(f"forbidden_key:{p}")
            if k == "type" and str(value) == "proposal_action":
                errs.append(f"forbidden_type:{p}")
            errs.extend(deep_scan_forbidden_keys(value, p))
    elif isinstance(data, list):
        for idx, item in enumerate(data):
            errs.extend(deep_scan_forbidden_keys(item, f"{path}[{idx}]"))
    return errs


def is_execution_phrase(text: str, phrases: Iterable[str] | None = None) -> bool:
    lowered = str(text or "").lower()
    active = [str(x).strip().lower() for x in list(phrases or STRATEGIC_EXECUTION_BYPASS_PHRASES) if str(x).strip()]
    if not active:
        return False
    pattern = r"\b(" + "|".join(re.escape(x) for x in active) + r")\b"
    return bool(re.search(pattern, lowered))

import queue
from typing import Optional

import numpy as np
import sounddevice as sd

from speech.io.devices import resolve_device
from speech.metrics.log import logger


class AudioIn:
    def __init__(
        self,
        sample_rate: int,
        frame_ms: int,
        gain: float = 1.0,
        device: Optional[int | str] = None,
        os_profile: str = "auto",
    ):
        self.sample_rate = sample_rate
        self.frame_ms = frame_ms
        self.blocksize = int(sample_rate * frame_ms / 1000)
        self.gain = gain
        self.device = device
        self.os_profile = os_profile
        self.frames: "queue.Queue[np.ndarray]" = queue.Queue(maxsize=100)
        self._stream = None
        self._dropped_frames = 0

    def start(self) -> None:
        def callback(indata, frames, time_info, status):
            if status:
                logger.warning("InputStream status: %s", status)
            pcm = (indata[:, 0].astype(np.float32) * self.gain).copy()
            try:
                self.frames.put_nowait(pcm)
            except queue.Full:
                self._dropped_frames += 1
                if self._dropped_frames == 1 or self._dropped_frames % 25 == 0:
                    logger.warning(
                        "AudioIn queue full; dropping oldest frame (drops=%s, qsize=%s)",
                        self._dropped_frames,
                        self.frames.qsize(),
                    )
                try:
                    _ = self.frames.get_nowait()
                except queue.Empty:
                    pass
                try:
                    self.frames.put_nowait(pcm)
                except queue.Full:
                    pass

        selected_device = resolve_device(self.device, kind="input", os_profile=self.os_profile)
        self._stream = sd.InputStream(
            samplerate=self.sample_rate,
            channels=1,
            dtype="float32",
            callback=callback,
            blocksize=self.blocksize,
            device=selected_device,
        )
        self._stream.start()
        logger.info("Mic capture started (device=%s os_profile=%s)", selected_device, self.os_profile)

    def read(self, timeout: float = 0.1) -> Optional[np.ndarray]:
        try:
            return self.frames.get(timeout=timeout)
        except queue.Empty:
            return None

    def stop(self) -> None:
        if self._stream is not None:
            self._stream.stop()
            self._stream.close()
            self._stream = None

from typing import Optional

import numpy as np
import sounddevice as sd

from speech.io.devices import resolve_device
from speech.metrics.log import logger


class AudioOut:
    def __init__(self, device: Optional[int | str] = None, os_profile: str = "auto"):
        self._current_sr: Optional[int] = None
        self.device = device
        self.os_profile = os_profile
        self._resolved_device: Optional[int] = None
        self._preferred_output_sr: Optional[int] = None

    @staticmethod
    def _resample_linear(pcm: np.ndarray, src_sr: int, dst_sr: int) -> np.ndarray:
        if src_sr == dst_sr:
            return np.asarray(pcm, dtype=np.float32)

        data = np.asarray(pcm, dtype=np.float32).reshape(-1)
        if data.size <= 1:
            return data

        ratio = float(dst_sr) / float(src_sr)
        out_len = max(1, int(round(data.size * ratio)))
        src_x = np.arange(data.size, dtype=np.float32)
        dst_x = np.linspace(0.0, float(data.size - 1), out_len, dtype=np.float32)
        return np.interp(dst_x, src_x, data).astype(np.float32)

    def _resolve_supported_sr(self, pcm: np.ndarray, sr: int) -> tuple[np.ndarray, int]:
        if self._resolved_device is None:
            self._resolved_device = resolve_device(self.device, kind="output", os_profile=self.os_profile)

        if self._preferred_output_sr is not None:
            try:
                sd.check_output_settings(device=self._resolved_device, samplerate=self._preferred_output_sr, channels=1, dtype="float32")
                return self._resample_linear(pcm, sr, self._preferred_output_sr), self._preferred_output_sr
            except Exception:
                self._preferred_output_sr = None

        try:
            sd.check_output_settings(device=self._resolved_device, samplerate=sr, channels=1, dtype="float32")
            self._preferred_output_sr = sr
            return np.asarray(pcm, dtype=np.float32), sr
        except Exception:
            pass

        # Windows hardware commonly supports these even when 24k/22.05k doesn't.
        candidates = [48000, 44100, 32000, 24000, 22050, 16000]
        for candidate_sr in candidates:
            try:
                sd.check_output_settings(device=self._resolved_device, samplerate=candidate_sr, channels=1, dtype="float32")
                self._preferred_output_sr = candidate_sr
                logger.warning("Output device does not support %sHz; resampling playback to %sHz", sr, candidate_sr)
                return self._resample_linear(pcm, sr, candidate_sr), candidate_sr
            except Exception:
                continue

        return np.asarray(pcm, dtype=np.float32), sr

    def play(self, pcm: np.ndarray, sr: int) -> None:
        self._current_sr = sr
        try:
            pcm32, out_sr = self._resolve_supported_sr(pcm, int(sr))
            sd.play(pcm32, out_sr, blocking=False, device=self._resolved_device)
        except Exception as exc:
            logger.exception("Audio playback failed: %s", exc)

    def stop(self) -> None:
        try:
            sd.stop()
        except Exception as exc:
            logger.warning("Audio stop failed: %s", exc)

